rss.channel:
ONIZUKA SHOP - Catalogue Officiel Bamako
{{ base_url }}
Catalogue officiel des climatiseurs, ventilateurs solaires, réfrigérateurs et électronique ONIZUKA SHOP au Grand Marché de Bamako (Dibidani)
{% for product in products %}{% if product.price > 0 or product.current_price > 0 %}


  {{ product.sku|default:product.id }}
  {{ product.category.slug|default:"onizuka-shop" }}
  {{ product.name|truncatechars:150 }}
  {{ product.short_description|default:product.description|default:product.name|striptags|truncatechars:950 }}
  {{ base_url }}{{ product.get_absolute_url }}
  {% if product.primary_image %}
  {{ base_url }}{{ product.primary_image.image.url }}
  {% else %}
  {{ base_url }}/static/images/pwa/icon-512.png
  {% endif %}
  {% for extra_img in product.images.all %}{% if not extra_img.is_primary and forloop.counter <= 10 %}
  {{ base_url }}{{ extra_img.image.url }}
  {% endif %}{% endfor %}
  {% if product.video_file %}
  {{ base_url }}{{ product.video_file.url }}
  {% endif %}
  {{ product.brand.name|default:"ONIZUKA SHOP" }}
  {{ product.sku|default:product.id }}
  no
  new
  {% if product.is_in_stock %}in stock{% else %}out of stock{% endif %}
  {{ product.stock|default:0 }}
  {{ product.price|floatformat:0 }} XOF
  {% if product.is_on_sale and product.sale_price and product.sale_price > 0 %}
  {{ product.sale_price|floatformat:0 }} XOF
  {% endif %}
  {{ product.category.name|default:"Électroménager & Climatisation" }}
  Home & Garden > Household Appliances

{% endif %}{% endfor %}
